'use strict';
const fs=require('node:fs'),path=require('node:path'),os=require('node:os'),cp=require('node:child_process');
const root=__dirname,config=path.resolve(root,'..','..'),edge=process.env.EDGE_PATH||'C:\\Program Files (x86)\\Microsoft\\Edge\\Application\\msedge.exe';
const dir=fs.mkdtempSync(path.join(os.tmpdir(),'dnd-description-check-'));
const mask=['Raven','Blank and white','Crying visage','Laughing visage','Skull','Butterfly'];
const origins=['Forester','Trapper','Homesteader','Guide','Exile or outcast','Bounty hunter','Pilgrim','Tribal nomad','Hunter-gatherer','Tribal marauder'];
function table(die,title,values){return '<table><thead><tr><th>'+die+'</th><th>'+title+'</th></tr></thead><tbody>'+values.map((v,i)=>'\n  <tr>\n<td><p>'+(i+1)+'</p></td>\n<td><p>'+v+'</p></td>\n</tr>\n').join('')+'</tbody></table>';}
const fixture={mask:'<p>A paragraph.</p>\n\n'+table('d6','Mask Appearance',mask),origin:table('d10','Origin',origins),unsafe:'<p>Safe <strong>bold</strong>.</p><script>window.bad=1</script><img src=x onerror="window.bad=1"><a href="javascript:alert(1)" onclick="alert(1)">Bad link</a>'};
const safe=v=>JSON.stringify(v).replaceAll('<','\\u003c');
const source=fs.readFileSync(path.join(root,'lib','description-renderer.js'),'utf8');
const styles=fs.readFileSync(path.join(root,'styles.css'),'utf8')+'\n'+fs.readFileSync(path.join(config,'snippets','dnd-2024-book.css'),'utf8');
const test="\nconst checks=[];function check(v,t){if(!v)throw Error(t);checks.push(t);}try{\n const target=document.querySelector('#description');module.exports.render(target,fixture.mask);let table=target.querySelector('table');check(table&&table.tBodies[0].rows.length===6,'d6 table structure and all six results');check(table.rows[0].cells[1].textContent==='Mask Appearance','Headers preserved');check(getComputedStyle(table).tableLayout==='auto','Reference layout independent from abilities');check(table.getBoundingClientRect().height<300,'Compact rows');\n module.exports.render(target,fixture.origin);table=target.querySelector('table');check(table.tBodies[0].rows.length===10&&table.rows[10].cells[1].textContent==='Tribal marauder','d10 table and all ten results');check(table.getBoundingClientRect().width<=target.clientWidth+2,'Table fits narrow card');\n module.exports.render(target,'<p>One.</p>\\n    <ul><li><strong>Two.</strong></li><li>Three.</li></ul>');check(target.querySelectorAll('li').length===2&&!!target.querySelector('strong'),'Lists and emphasis preserved');check(getComputedStyle(target).whiteSpace==='normal','No visible HTML indentation');\n module.exports.render(target,'One\\n\\n\\n\\n Two');check(target.querySelectorAll('p').length===2,'Bounded paragraph spacing');\n target.replaceChildren();module.exports.upgrade(target,fixture.mask);target.setText('Flattened original renderer output');check(!!target.querySelector('table'),'Lazy fill preserves source table');target.setText('Updated fallback.\\n\\nSecond paragraph.');check(target.querySelectorAll('p').length===2,'Fallback updates work');\n module.exports.render(target,fixture.unsafe);check(!target.querySelector('script,img,[onclick],[onerror]')&&!target.querySelector('a').hasAttribute('href')&&!window.bad,'Active HTML and unsafe URLs removed');check(!!target.querySelector('strong'),'Safe formatting remains');\n document.querySelector('#status').textContent='PASS: '+checks.join('; ');document.body.dataset.result='pass';\n}catch(e){document.querySelector('#status').textContent='FAIL: '+e.stack;document.body.dataset.result='fail';}\n";
const html='<!doctype html><meta charset="utf-8"><style>'+styles+'\nbody{background:#252925;color:#ddd;--text-normal:#ddd;--text-muted:#aaa;--background-modifier-border:#666}.dndcustom-mm-view{width:330px}#status{white-space:pre-wrap;font:12px Arial}</style><body><pre id="status">Testing…</pre><div class="dndcustom-mm-view dnd-book"><div id="description" class="dndcustom-reference-description"></div></div><script>const fixture='+safe(fixture)+';const module={exports:{}};'+source+'\n'+test+'</script>';
const file=path.join(dir,'test.html');fs.writeFileSync(file,html);
cp.execFile(edge,['--headless=new','--no-first-run','--disable-gpu','--hide-scrollbars','--user-data-dir='+path.join(dir,'profile'),'--virtual-time-budget=1000','--dump-dom','--window-size=700,1100',new URL('file:///'+file.replaceAll('\\','/')).href],{windowsHide:true,maxBuffer:3000000},(error,stdout)=>{if(error){console.error(error);process.exitCode=1;return;}const result=stdout.match(/<pre id="status">([\s\S]*?)<\/pre>/)?.[1]||'FAIL: no browser result';console.log(result);if(!stdout.includes('data-result="pass"'))process.exitCode=1;});
